        const s = 9 + R() * 12;
        g.scale(s * (1.3 + R() * 0.6), s * 0.55, s);
        g.translate((p - puffs / 2) * 13 + R() * 5, R() * 4, R() * 8);
        g.rotateY(ang + Math.PI / 2);
        g.translate(Math.cos(ang) * dist, y, Math.sin(ang) * dist);
