        let hh = ring.h * (0.35 + 0.65 * Math.abs(Math.sin(a * 3.1 + ring.k) * 0.6 + Math.sin(a * 7.3 + 1.7 * ring.k) * 0.3 + (R() - 0.5) * 0.35));
